const fs = require("fs/promises");
const path = require("path");

const discord = require("discord.js");

const Canvas = require('canvas');

const ObjectDetection = require('../../util/object-detection');
const TempFolder = require('../../util/temp-folder');

class Command {
    constructor() {
        this.name = "eyes";
        this.description = "Adds the eye emoji onto the eyes in the image given.";
        this.attributes = {
            unlisted: false,
            lockedToCommands: true,
            permission: 0,
        };

        this.alias = ["eye"];
    }

    async handle(message, args, util) {
        const [imageBuffer] = await util.getInputImagesForCommand(message);
        if (!imageBuffer) return;
        
        // actually start doing stuff
        const jobName = TempFolder.makeTempName("where");
        const temporaryFolder = new TempFolder(jobName);
        await temporaryFolder.createAndDestroy(async (tempDir) => {
            const image = await Canvas.loadImage(imageBuffer);
            const eyeImage = await Canvas.loadImage("./assets/eye.png");

            // resize the image (we reuse this canvas for later)
            const resizedHeight = 1024;
            const aspectRatio = image.width / image.height;
            const resizedWidth = Math.round(resizedHeight * aspectRatio);
            if (resizedWidth > 8192) throw new Error("Image is wider than 4x the height");
            
            const canvas = Canvas.createCanvas(resizedWidth, resizedHeight);
            const ctx = canvas.getContext("2d");
            ctx.drawImage(image, 0, 0, canvas.width, canvas.height);

            // download
            const imagePath = path.join(tempDir, "image.png");
            await fs.writeFile(imagePath, canvas.toBuffer("image/png"));

            // look at the image
            await message.channel.sendTyping();

            // NOTE: I believe mentioning unnecessary objects can help it find sub-elements important
            const objectList = ["main subject", "head", "eye", "mouth"];
            const objects = await ObjectDetection.predict(imagePath, objectList);
            
            const eyes = objects.eye;
            if (!eyes) return message.reply("I am not Noticing 👀  any eyes");

            // DISCLOSURE: locals ai filtering the noise in the objecte detection
            // Filter out detection noise that may represent larger objects like faces or heads.
            // Keep true eye detections while allowing any number of them (1 to infinity).
            const imgArea = canvas.width * canvas.height;
            const eyesToDraw = eyes.filter(box => {
                const w = box.box[2] - box.box[0];
                const h = box.box[3] - box.box[1];
                const area = w * h;
                // Ignore boxes that are too small to be an eye
                if (area < 20 * 20) return false;
                // Ignore boxes that occupy a large portion of the image – likely not a single eye
                if (area / imgArea > 0.15) return false;
                return box.score > 0.1;
            });
            
            if (eyesToDraw.length <= 0) return message.reply("I am not Noticing 👀  any eyes");
            for (const box of eyesToDraw) {
                const width = box.box[2] - box.box[0];
                const height = box.box[3] - box.box[1];

                // DISCLOSURE: scaling  done by the locals ai like usual
                // Scale eye image based on the width of the detected eye box
                const aspectRatio = eyeImage.height / eyeImage.width;
                const eyeHeight = Math.round(width * aspectRatio);
                // dont use the funky ai ehh if the box is taller than the calcuated eye height
                const actualEyeHeight = eyeHeight > height ? eyeHeight : height;
                const offsetY = (height - actualEyeHeight) / 2;
                ctx.drawImage(eyeImage, box.box[0], box.box[1] + offsetY, width, actualEyeHeight);
            }

            const drawnBuffer = canvas.toBuffer("image/png");
            message.reply({
                content: `Generated by <@${message.author.id}>`,
                files: [drawnBuffer],
                allowedMentions: {
                    parse: [],
                    users: [],
                    roles: [],
                    repliedUser: false
                }
            });
        });
    }
    async invoke(message, args, util) {
        const canDo = util.request("heavyExternalStuff");
        if (!canDo) return message.reply("disabled (im probably playing a game)");

        await this.handle(message, args, util);
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;